/** Widths generated by scripts/optimize-images.mjs (`npm run images`) for every project screenshot. */
export const SCREENSHOT_WIDTHS = [480, 960, 1600, 2560] as const;

export type ScreenshotWidth = (typeof SCREENSHOT_WIDTHS)[number];

export interface ResponsiveImage {
  src: string;
  srcset: string | null;
}

/**
 * Builds `src`/`srcset` for a screenshot stored as `<path>-<width>.webp`.
 * Paths ending in `.svg` are vector images and are used as-is.
 */
export function responsiveImage(path: string, fallbackWidth: ScreenshotWidth = 1600): ResponsiveImage {
  if (path.endsWith('.svg')) {
    return { src: path, srcset: null };
  }
  return {
    src: `${path}-${fallbackWidth}.webp`,
    srcset: SCREENSHOT_WIDTHS.map((width) => `${path}-${width}.webp ${width}w`).join(', '),
  };
}
